use verus::prelude::*;

/// Appends an element `b` to the end of vector `a`, returning a new vector.
/// 
/// Specification:
///   - The original vector `a` is not modified.
///   - The result has length one greater than `a`.
///   - The first `a.len()` elements of the result are exactly the elements of `a`.
///   - The last element of the result is `b`.
#[requires(true)]
#[ensures(a.len() == old(a.len()))]
#[ensures(result.len() == old(a.len()) + 1)]
#[ensures(forall(|i: usize| i < a.len() ==> result[i] == a[i]))]
#[ensures(result[a.len()] == b)]
fn append(a: &Vec<i32>, b: i32) -> Vec<i32> {
    // Allocate a new Vec with capacity for all old elements plus one more.
    let mut result = Vec::with_capacity(a.len() + 1);

    // Copy the existing elements
    result.extend_from_slice(a);
    // After copying, the length must equal a.len()
    assert(result.len() == a.len());

    // Append the new element
    result.push(b);
    // After pushing, the length must be a.len() + 1
    assert(result.len() == a.len() + 1);

    result
}

